<script>document.addEventListener('DOMContentLoaded',()=>{const headerLogo=document.querySelector('.school-header .school-logo img');if(headerLogo){headerLogo.src='/assets/shoudu-logo-header.png';headerLogo.dataset.defaultLogo=headerLogo.src;headerLogo.dataset.stickyLogo=headerLogo.src}const gallery=document.querySelector('.school-moment-grid');if(gallery&&!gallery.querySelector('.school-moment-feature')){const feature=document.createElement('figure');feature.className='school-moment-feature';feature.innerHTML='<img src="/assets/shoudu-community.jpg" alt="Children learning together at Shoudu" loading="lazy"><figcaption><span>Connection</span>Growing together</figcaption>';gallery.append(feature)}const footer=document.querySelector('.school-footer');footer?.querySelector('.school-footer-promise')?.remove();const logo=footer?.querySelector('.school-footer-brand img');if(logo){logo.src='/assets/shoudu-logo-light.webp';logo.removeAttribute('data-default-logo');logo.removeAttribute('data-sticky-logo')}const film=document.querySelector('.school-motion video'),toggle=document.querySelector('[data-motion-toggle]');if(film&&toggle)toggle.addEventListener('click',()=>{if(film.paused){film.play().catch(()=>{});toggle.classList.add('is-playing');toggle.querySelector('span').textContent='Pause film'}else{film.pause();toggle.classList.remove('is-playing');toggle.querySelector('span').textContent='Play film'}})});</script>
<script>(()=>{const button=document.querySelector('[data-school-back-to-top]'),divider=document.querySelector('.school-footer-bottom'),content=document.querySelector('main');if(!button)return;let scheduled=false;const render=()=>{scheduled=false;button.classList.toggle('is-visible',window.scrollY>480);const dividerTop=divider?.getBoundingClientRect().top??window.innerHeight;if(dividerTop>0&&dividerTop<window.innerHeight)button.style.bottom=`${window.innerHeight-dividerTop+10}px`;else button.style.removeProperty('bottom')};const update=()=>{if(scheduled)return;scheduled=true;requestAnimationFrame(render)};addEventListener('scroll',update,{passive:true});addEventListener('resize',update,{passive:true});addEventListener('DOMContentLoaded',update,{once:true});addEventListener('load',update,{once:true});document.fonts?.ready.then(update);if('ResizeObserver'in window){const observer=new ResizeObserver(update);if(content)observer.observe(content);if(divider)observer.observe(divider)}button.addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));update()})();</script>
